def transform(grid):
    """Highlight positions where both equal-sized panels contain their shared color."""
    h, w = len(grid), len(grid[0])
    if h % 2 == 1 and len(set(grid[h // 2])) == 1:
        r = h // 2
        first, second = grid[:r], grid[r + 1:]
        first_colors = {v for row in first for v in row}
        second_colors = {v for row in second for v in row}
        common = first_colors & second_colors
        target = next(iter(common)) if common else 0
        return [[3 if first[i][j] == target and second[i][j] == target else target
                 for j in range(w)] for i in range(len(second))]
    if w % 2 == 1 and all(row[w // 2] == grid[0][w // 2] for row in grid):
        c = w // 2
        first = [row[:c] for row in grid]
        second = [row[c + 1:] for row in grid]
        first_colors = {v for row in first for v in row}
        second_colors = {v for row in second for v in row}
        common = first_colors & second_colors
        target = next(iter(common)) if common else 0
        return [[3 if first[i][j] == target and second[i][j] == target else target
                 for j in range(c)] for i in range(h)]
    raise ValueError("no centered solid panel separator found")
